sp_css.css:
/* ============================================================
   VELLUM — WRM Service Portal theme
   Light is the default. Dark is applied by adding the class
   "dark" to <body>, which we wire up in a later story.
   ============================================================ */

:root {
  /* --- neutrals: paper and ink --- */
  --paper:     #F6F2EA;  /* page background */
  --surface:   #FFFDF9;  /* cards, panels  */
  --surface-2: #F0EBE1;  /* hover, thumbs  */
  --ink:       #3A342C;  /* primary text   */
  --ink-2:     #6B6157;  /* secondary text */
  --ink-3:     #8B8175;  /* labels, hints  */
  --line:      #E2DACC;  /* borders        */

  /* --- the single accent --- */
  --clay:       #B0705A;
  --clay-press: #99604C;  /* hover / active */
  --on-clay:    #FFFDF9;  /* text on clay   */

  /* --- status tints: these map to available_status --- */
  --free-bg: #E4EEEC;  --free-fg: #3F6862;
  --held-bg: #F2EADA;  --held-fg: #7E6634;
  --out-bg:  #F4E5E2;  --out-fg:  #8A5750;

  /* --- the signature: sharp corner is ALWAYS bottom-left.
         Order is top-left, top-right, bottom-right, bottom-left. --- */
  --r-pill:  99px 99px 99px 4px;
  --r-soft:  12px 12px 12px 3px;
  --r-input: 10px 10px 10px 3px;
  --r-card:  18px 18px 18px 3px;
}

/* Dark mode: same variable names, different values, so no
   component CSS below this point ever needs to know about it. */
body.dark {
  --paper: #1E1B18; --surface: #26221E; --surface-2: #2E2924;
  --ink:   #EDE7DD; --ink-2:   #B8AFA3; --ink-3:     #9A9086;
  --line:  #3B352F;
  --clay:  #C98D74; --clay-press: #D89C83; --on-clay: #241F1B;
  --free-bg: #26302E; --free-fg: #93BAB3;
  --held-bg: #332E24; --held-fg: #C7AC77;
  --out-bg:  #332826; --out-fg:  #C99B93;
}

/* ---------- base ---------- */
body { background: var(--paper); color: var(--ink); }
.navbar, .sp-page-root { background: var(--paper); }

/* ---------- Bootstrap overrides ----------
   ServiceNow's compiled CSS already sets radius on these, so we
   have to be at least as specific. Scoping to .sp-page usually
   wins without needing !important — if a control stays square,
   that's the first thing to check. */
.sp-page .btn,
.sp-page .label,
.sp-page .badge      { border-radius: var(--r-pill); }

.sp-page .panel,
.sp-page .well       { border-radius: var(--r-card);
                       background: var(--surface);
                       border-color: var(--line); }

.sp-page .form-control,
.sp-page .input-group-addon { border-radius: var(--r-input);
                              background: var(--surface);
                              border-color: var(--line);
                              color: var(--ink); }

/* ---------- buttons ---------- */
.sp-page .btn-primary {
  background: var(--clay);
  border-color: var(--clay);
  color: var(--on-clay);
  box-shadow: inset 0 0 0 1px rgba(255,255,255,.22);
}
.sp-page .btn-primary:hover,
.sp-page .btn-primary:focus {
  background: var(--clay-press);
  border-color: var(--clay-press);
}
.sp-page .btn-default {
  background: transparent;
  border-color: var(--line);
  color: var(--ink-2);
}
/* Keyboard users need to see where they are. */
.sp-page .btn:focus-visible { outline: 2px solid var(--clay); outline-offset: 3px; }

/* ---------- required-field chips on catalog items ----------
   Catalog uses its own classes here, not Bootstrap's
   .label-danger. Buttons also carry a UA border, so we
   flatten that too. */
.sc-reqd-info-btn,
.sc-field-error-label {
  background: var(--out-bg) !important;
  color: var(--out-fg) !important;
  border: 1px solid var(--out-bg) !important;
  border-radius: var(--r-pill);
  font-weight: 500;
}

.sc-reqd-info-btn:hover,
.sc-reqd-info-btn:focus {
  background: var(--out-fg) !important;
  color: var(--surface) !important;
}
